#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    long long maxProfit(std::vector<int>& prices, std::vector<int>& strategy, int k) {
        int n = prices.size();
        long long base_profit = 0;
        for (int i = 0; i < n; ++i) {
            base_profit += 1LL * prices[i] * strategy[i];
        }

        long long cur_gain = 0;
        for (int i = 0; i < std::min(k, n); ++i) {
            cur_gain += 1LL * prices[i] * (1 - strategy[i]);
        }
        long long max_gain = std::max(0LL, cur_gain);

        for (int i = k; i < n; ++i) {
            cur_gain += 1LL * prices[i] * (1 - strategy[i]);
            cur_gain -= 1LL * prices[i - k] * (1 - strategy[i - k]);
            max_gain = std::max(max_gain, cur_gain);
        }
        return base_profit + max_gain;
    }
};

class Solution {
    public long maxProfit(int[] prices, int[] strategy, int k) {
        int n = prices.length;
        long baseProfit = 0;
        for (int i = 0; i < n; i++) {
            baseProfit += (long) prices[i] * strategy[i];
        }

        long curGain = 0;
        int win = Math.min(k, n);
        for (int i = 0; i < win; i++) {
            curGain += (long) prices[i] * (1 - strategy[i]);
        }
        long maxGain = Math.max(0, curGain);

        for (int i = k; i < n; i++) {
            curGain += (long) prices[i] * (1 - strategy[i]);
            curGain -= (long) prices[i - k] * (1 - strategy[i - k]);
            maxGain = Math.max(maxGain, curGain);
        }
        return baseProfit + maxGain;
    }
}

